    options: ['`azcopy copy "<source>" "<destination>" --recursive=true`', '`azcopy sync "<source>" "<destination>" --delete-destination=true`', '`az storage blob upload-batch --source "<source>" --destination "<destination>"`', '`azcopy list "<source>" --output table`'],
